const MAIN_PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Dark Protocol \u2014 Private transfers on Solana, with the math checked</title>\n<meta name=\"description\" content=\"Dark Protocol is a privacy pool for Solana. This page explains, in plain language, how the code is being formally verified \u2014 proving the pool's rules hold for every possible action, not just the ones we tested.\">\n<style>\n  :root{\n    --bg:#05060a; --bg2:#0a0c14; --card:#0d1019; --line:#1c2130;\n    --text:#e8eaf2; --muted:#9aa3b8; --faint:#6b7390;\n    --purple:#9945FF; --green:#14F195; --amber:#ffb454; --red:#ff6b7a;\n    --grad:linear-gradient(92deg,#9945FF 0%,#14F195 100%);\n  }\n  *{margin:0;padding:0;box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,Helvetica,Arial,sans-serif;line-height:1.65;-webkit-font-smoothing:antialiased}\n  .mono{font-family:ui-monospace,\"SF Mono\",SFMono-Regular,Menlo,Consolas,monospace}\n  .wrap{max-width:880px;margin:0 auto;padding:0 22px}\n  a{color:var(--green);text-decoration:none}\n  a:hover{text-decoration:underline}\n\n  /* header */\n  header{border-bottom:1px solid var(--line);background:rgba(5,6,10,.85);position:sticky;top:0;backdrop-filter:blur(8px);z-index:10}\n  .nav{display:flex;align-items:center;justify-content:space-between;padding:14px 0}\n  .brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.04em}\n  .brand .dot{width:11px;height:11px;border-radius:3px;background:var(--grad)}\n  .brand small{color:var(--muted);font-weight:500;letter-spacing:.08em}\n  .nav .mono{font-size:12px;color:var(--muted)}\n\n  /* hero */\n  .hero{padding:72px 0 46px;text-align:left}\n  .kicker{font-size:12px;letter-spacing:.28em;color:var(--green);text-transform:uppercase;margin-bottom:18px}\n  h1{font-size:clamp(34px,6vw,54px);line-height:1.12;font-weight:800;letter-spacing:-.01em}\n  h1 .grad{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .lede{margin-top:20px;font-size:19px;color:var(--muted);max-width:640px}\n  .pills{display:flex;flex-wrap:wrap;gap:10px;margin-top:28px}\n  .pill{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--card);border-radius:999px;padding:7px 14px;font-size:13px}\n  .pill .s{width:8px;height:8px;border-radius:50%}\n  .s-green{background:var(--green)} .s-amber{background:var(--amber)} .s-grey{background:#5a6480}\n  .s-amber{box-shadow:0 0 0 0 rgba(255,180,84,.5);animation:pulse 2s infinite}\n  @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(255,180,84,.45)}70%{box-shadow:0 0 0 8px rgba(255,180,84,0)}100%{box-shadow:0 0 0 0 rgba(255,180,84,0)}}\n\n  /* sections */\n  section{padding:38px 0;border-top:1px solid var(--line)}\n  h2{font-size:26px;font-weight:750;letter-spacing:-.01em;margin-bottom:8px}\n  h2 .num{color:var(--purple);font-family:ui-monospace,Menlo,monospace;font-size:18px;margin-right:10px}\n  .sub{color:var(--muted);margin-bottom:22px;max-width:680px}\n  p{margin-bottom:14px;color:#cdd3e2}\n  p strong, li strong{color:var(--text)}\n\n  .card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px 24px;margin-bottom:16px}\n  .card h3{font-size:17px;margin-bottom:6px}\n  .card p{margin-bottom:0;color:var(--muted);font-size:15px}\n  .analogy{border-left:3px solid var(--purple);background:linear-gradient(90deg,rgba(153,69,255,.08),transparent 65%)}\n  .analogy p{color:#cdd3e2}\n\n  /* promise list */\n  .promise{display:flex;gap:16px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px 22px;margin-bottom:12px}\n  .promise .n{flex:0 0 34px;height:34px;border-radius:10px;background:var(--grad);color:#05060a;font-weight:800;display:flex;align-items:center;justify-content:center;font-size:16px}\n  .promise h3{font-size:16.5px;margin-bottom:3px}\n  .promise p{color:var(--muted);font-size:14.5px;margin:0}\n\n  /* ladder */\n  .step{display:flex;gap:16px;padding:16px 0;border-bottom:1px dashed var(--line)}\n  .step:last-child{border-bottom:none}\n  .step .tag{flex:0 0 92px}\n  .tag span{display:inline-block;font-size:11px;letter-spacing:.12em;padding:4px 9px;border-radius:6px;border:1px solid var(--line);color:var(--muted)}\n  .tag .done{color:var(--green);border-color:rgba(20,241,149,.4)}\n  .tag .live{color:var(--amber);border-color:rgba(255,180,84,.45)}\n  .step h3{font-size:16px;margin-bottom:2px}\n  .step p{color:var(--muted);font-size:14.5px;margin:0}\n\n  .honest{background:rgba(255,180,84,.05);border:1px solid rgba(255,180,84,.28);border-radius:14px;padding:22px 24px}\n  .honest h3{color:var(--amber);font-size:16px;margin-bottom:10px}\n  .honest li{color:#cdd3e2;font-size:15px;margin-bottom:8px;margin-left:18px}\n\n  .faq h3{font-size:16px;margin:18px 0 4px}\n  .faq p{color:var(--muted);font-size:15px}\n\n  footer{border-top:1px solid var(--line);padding:34px 0 54px;color:var(--muted);font-size:13.5px}\n  footer .row{display:flex;flex-wrap:wrap;gap:8px 22px;justify-content:space-between}\n  .fineprint{margin-top:14px;font-size:12.5px;color:#5f6b7f}\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"wrap nav\">\n    <div class=\"brand\"><span class=\"dot\"></span>DARK&nbsp;PROTOCOL <small>\u00b7 BY DARKX402</small></div>\n    <div class=\"mono\">solana \u00b7 zero-knowledge \u00b7 formally verified</div>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <!-- HERO -->\n  <div class=\"hero\">\n    <div class=\"kicker\">Privacy pool for Solana</div>\n    <h1>Send privately.<br><span class=\"grad\">Prove it can't be cheated.</span></h1>\n    <p class=\"lede\">Dark Protocol lets you deposit SOL into a shared pool and withdraw it to a fresh wallet \u2014 with no public link between the two. And because a privacy pool is only worth using if its rules can't be bent, we're having the code <strong style=\"color:var(--text)\">formally verified</strong>: machine-checked proof that the rules hold for <em>every</em> possible action, not just the ones we thought to test.</p>\n    <div class=\"pills\">\n      <span class=\"pill\"><span class=\"s s-green\"></span>Live on Solana <strong>devnet</strong> (test network)</span>\n      <span class=\"pill\"><span class=\"s s-amber\"></span>Formal verification \u2014 <strong>in progress</strong></span>\n      <span class=\"pill\"><span class=\"s s-grey\"></span>Mainnet \u2014 <strong>not launched yet</strong></span>\n    </div>\n  </div>\n\n  <!-- ARTICLE CARD -->\n  <section style=\"border-top:none;padding-top:6px\">\n    <div class=\"card\" style=\"border-left:3px solid var(--green);background:linear-gradient(90deg,rgba(20,241,149,.06),transparent 65%)\">\n      <div style=\"font-size:11px;letter-spacing:.24em;color:var(--green);text-transform:uppercase;margin-bottom:8px\">New \u00b7 The full story</div>\n      <h3 style=\"font-size:21px;line-height:1.3;margin-bottom:8px\"><a href=\"/dark-protocol/article\" style=\"color:var(--text)\">Dark Protocol: A Year of Building Private Solana \u2014 and the Proof We Ran Out of Fuel to Finish</a></h3>\n      <p style=\"margin-bottom:12px\">How we built it, how we tried to break it, and the formal verification we're seeking sponsorship to finish.</p>\n      <a href=\"/dark-protocol/article\" style=\"font-weight:600\">Read the article \u2192</a>\n    </div>\n  </section>\n\n  <!-- WHAT IT IS -->\n  <section>\n    <h2><span class=\"num\">01</span>What is Dark Protocol?</h2>\n    <p class=\"sub\">On a public blockchain, every payment leaves a trail anyone can follow. Dark Protocol breaks the trail \u2014 without asking you to trust the people running it.</p>\n    <div class=\"card analogy\">\n      <h3>Think of a cloakroom</h3>\n      <p>You hand over your coat and get a ticket. Later, anyone holding a valid ticket can claim a coat \u2014 but nobody watching can tell which coat belonged to which person, because the tickets don't name anyone. Dark Protocol is a cloakroom for SOL: your deposit is the coat, a cryptographic <strong>note</strong> only you hold is the ticket, and a piece of mathematics called a <strong>zero-knowledge proof</strong> is how you show \"I have a valid ticket\" without revealing which deposit was yours.</p>\n    </div>\n    <div class=\"card\">\n      <h3>The catch with every cloakroom</h3>\n      <p>It only works if the cloakroom itself can't cheat: it must never hand out more coats than were checked in, never let someone claim with a forged ticket, never let the same ticket be spent twice, and never let the staff walk off with the coats. In Dark Protocol there's no staff and no office \u2014 there's only code, running on Solana, that anyone can read. So the real question is: <strong>how do we know the code actually enforces those rules?</strong> That's what the rest of this page is about.</p>\n    </div>\n  </section>\n\n  <!-- TESTING VS PROVING -->\n  <section>\n    <h2><span class=\"num\">02</span>Testing checks examples. Proof checks everything.</h2>\n    <p class=\"sub\">Most software is tested: you try a few thousand scenarios and check the right thing happens. That catches a lot \u2014 but an attacker only needs the <em>one</em> scenario nobody tried.</p>\n    <p><strong>Formal verification</strong> is different. A specialised system reads the actual program code and tries to <em>prove</em>, mathematically, that a rule holds for <strong>every possible sequence of actions, in any order, with any amounts</strong> \u2014 the way you'd prove a theorem about all numbers, not just the ones you tested. If it can't prove a rule, it doesn't shrug: it produces a <strong>concrete counterexample</strong> \u2014 an exact recipe of steps that breaks the rule \u2014 so the bug can be fixed and the proof run again.</p>\n    <p>On <strong>November 18, 2026</strong>, we submitted the Dark Protocol program to <strong>Aristotle</strong>, a formal-verification system built by <strong>Harmonic</strong>, under a project named <span class=\"mono\">dark-protocol-pilot</span>. The run is in progress now. When it finishes, we will publish the results on this page <strong>either way</strong> \u2014 proved, or refuted with the counterexample.</p>\n  </section>\n\n  <!-- THE SIX PROMISES -->\n  <section>\n    <h2><span class=\"num\">03</span>The six promises we asked it to prove</h2>\n    <p class=\"sub\">These are the exact properties in the submitted specification, translated into plain language. In cloakroom terms first, then in real terms.</p>\n\n    <div class=\"promise\"><div class=\"n\">1</div><div>\n      <h3>Money is conserved</h3>\n      <p>The pool can never pay out more than was put in. Every lamport is accounted for: the total paid out never exceeds the total deposited, no matter what sequence of deposits and withdrawals anyone tries \u2014 and sending money <em>to</em> the pool as a \"donation\" can't inflate what it owes.</p>\n    </div></div>\n\n    <div class=\"promise\"><div class=\"n\">2</div><div>\n      <h3>No withdrawal without a valid ticket</h3>\n      <p>Funds move only after the program has checked, in order: the amount is real, the deposit history being claimed against is genuine, the pool can afford it, and the zero-knowledge proof verifies. A failed check cancels the whole withdrawal \u2014 including the \"ticket used\" stamp, so an honest user never loses their note to a rejected attempt.</p>\n    </div></div>\n\n    <div class=\"promise\"><div class=\"n\">3</div><div>\n      <h3>The amount is sealed to the note</h3>\n      <p>When you deposit, the amount is cryptographically sealed into your note by the program itself \u2014 it can't be edited afterwards. This kills the classic drain: deposit a speck, then claim the note says a fortune. We already watched that attack fail live on the test network; this property asks for the proof that it can <em>never</em> work.</p>\n    </div></div>\n\n    <div class=\"promise\"><div class=\"n\">4</div><div>\n      <h3>There is no backdoor \u2014 not even for us</h3>\n      <p>The program records who deployed it, but that identity authorises nothing. The only way money ever leaves the pool is the proof-checked withdrawal path. No admin key, no operator override, no \"emergency\" shortcut.</p>\n    </div></div>\n\n    <div class=\"promise\"><div class=\"n\">5</div><div>\n      <h3>Honest withdrawals always work</h3>\n      <p>Security that locks everyone out is just a different failure. If your proof is valid, your note is unspent, and the pool holds your money, your withdrawal goes through \u2014 and if a withdrawal ever fails, the failure has a specific named reason, never a mystery. This is the property that turns \"it worked in our rehearsal\" into \"it must work, under these stated conditions.\"</p>\n    </div></div>\n\n    <div class=\"promise\"><div class=\"n\">6</div><div>\n      <h3>The pool's memory can't be rewritten</h3>\n      <p>The pool keeps a rolling record of every deposit. That record is append-only: entries are produced by the program itself, old entries age out only after exactly 32 newer ones, and the record's summary always matches a from-scratch recount of every deposit ever made.</p>\n    </div></div>\n\n    <p style=\"color:var(--muted);font-size:14.5px\">Plus a zeroth promise underneath all of them: on any valid input, the program never crashes or misbehaves arithmetically \u2014 no overflows, no panics, checked maths only.</p>\n  </section>\n\n  <!-- HOW WE GOT HERE -->\n  <section>\n    <h2><span class=\"num\">04</span>How we got here</h2>\n    <p class=\"sub\">Formal verification is the newest layer, not the only one. Dark Protocol was built the slow way:</p>\n\n    <div class=\"step\"><div class=\"tag\"><span class=\"done\">DONE</span></div><div>\n      <h3>Independent audit \u2014 39 findings</h3>\n      <p>A full audit of the original code found 39 problems, including critical ones: checks that were faked, proofs that weren't really checked. We published the findings and ordered a rewrite instead of patching over them.</p>\n    </div></div>\n\n    <div class=\"step\"><div class=\"tag\"><span class=\"done\">DONE</span></div><div>\n      <h3>Rewrite, then a hostile re-audit</h3>\n      <p>The rewritten program was audited again \u2014 and the re-audit caught one more critical flaw (a deposit could be unbound from its amount: the drain in promise 3). It was fixed, and the fix is now the thing being formally proved.</p>\n    </div></div>\n\n    <div class=\"step\"><div class=\"tag\"><span class=\"done\">DONE</span></div><div>\n      <h3>Full dress rehearsal on the test network</h3>\n      <p>Deposits, withdrawals, a withdrawal through a relayer, a replay attack (spending the same note twice \u2014 rejected), a tampered amount (rejected), and the 1-lamport drain attempt (failed, as designed). Every result matched the ledger to the lamport.</p>\n    </div></div>\n\n    <div class=\"step\"><div class=\"tag\"><span class=\"live\">IN PROGRESS</span></div><div>\n      <h3>Formal verification \u2014 Aristotle pilot</h3>\n      <p>The six promises above, submitted November 18, 2026. Results will be posted here when the run completes, including anything it refutes.</p>\n    </div></div>\n\n    <div class=\"step\"><div class=\"tag\"><span class=\"live\">IN PROGRESS</span></div><div>\n      <h3>The setup ceremony</h3>\n      <p>The privacy proofs rely on a one-time setup that must be generated in public, by several independent people each adding their own secret randomness. The mathematics guarantees the setup is sound if even <em>one</em> participant was honest and destroyed their secret. Our ceremony uses the public Hermez setup (54 contributors) plus five contributors of our own and a public randomness beacon. Details and the contributor list will be published with the transcript.</p>\n    </div></div>\n  </section>\n\n  <!-- HONEST LIMITS -->\n  <section>\n    <h2><span class=\"num\">05</span>What verification does <em>not</em> do</h2>\n    <div class=\"honest\">\n      <h3>Honest limits, on purpose</h3>\n      <ul>\n        <li><strong>It's not finished.</strong> The run is in progress. Until results are published here, \"formally verified\" describes the process we've started \u2014 not a result we've received.</li>\n        <li><strong>It verifies the program, not the privacy circuit.</strong> The zero-knowledge circuit's soundness rests on the setup ceremony (above) and the audit trail \u2014 a different layer, checked a different way.</li>\n        <li><strong>Two steps are taken on stated assumptions.</strong> The specification says openly that the proof treats the pool's hashing and the proof-checker itself as trusted building blocks, and says exactly where. If the verifier can only prove a promise <em>under</em> those assumptions, the result will say so \u2014 that's a feature, not fine print.</li>\n        <li><strong>It says nothing about speed or cost.</strong> A separate failure class \u2014 operations too expensive to fit in a transaction \u2014 is handled by measurement and rehearsal, not proof. (It bit us once, on the test network, and the fix is part of why the rehearsal mattered.)</li>\n        <li><strong>This is still a test-network system.</strong> Dark Protocol runs on Solana devnet. Mainnet comes only after the ceremony and the verification results are in \u2014 and that decision will be announced, not slipped in.</li>\n      </ul>\n    </div>\n  </section>\n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <h2><span class=\"num\">06</span>Questions</h2>\n    <h3>What happens if the verifier finds a bug?</h3>\n    <p>Then it did its job. A refuted promise comes back with a concrete counterexample \u2014 an exact sequence of steps that breaks the rule. We fix the code, and the fixed version gets proved again. Finding the bug in a proof is infinitely cheaper than finding it in production.</p>\n    <h3>Who is Harmonic, and what is Aristotle?</h3>\n    <p>Harmonic is the company behind Aristotle, an automated theorem-proving system that translates Rust programs into mathematical models and proves (or refutes) stated properties about them. In its published Solana case study, it produced 28 proved results on a production order-book program \u2014 and found two real bugs, which were fixed. That's the standard we're holding Dark Protocol to.</p>\n    <h3>Did you have to hand over the code?</h3>\n    <p>Yes \u2014 verification means the verifier reads the real program, all of it, exactly as deployed on the test network. The submitted bundle contained only the program source and the specification: no keys, no credentials, nothing that could move funds.</p>\n    <h3>When will results be published?</h3>\n    <p>When the run completes \u2014 these proofs take minutes to days. This page will be updated with the per-promise outcomes and the verifier's own statement of what it did and didn't cover.</p>\n  </section>\n\n  <footer>\n    <div class=\"row\">\n      <div><strong style=\"color:var(--text)\">DARK PROTOCOL</strong> \u00b7 a Dark DeFi project \u00b7 darkx402.com</div>\n      <div class=\"mono\">program (devnet): 2GmpuVGfFVfhiqUWrrhkkWBk3i8TpbTuqyiZNXETA5kL</div>\n    </div>\n    <p class=\"fineprint\">Status as of November 18, 2026: live on Solana devnet for testing; formal verification in progress (Aristotle project \u201cdark-protocol-pilot\u201d); mainnet not launched. Nothing on this page is financial advice, and a system being verified is not a guarantee \u2014 it is evidence, published so you can weigh it yourself.</p>\n  </footer>\n\n</div>\n</body>\n</html>\n";
const ARTICLE_PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Dark Protocol: A Year of Building Private Solana \u2014 and the Proof We Ran Out of Fuel to Finish</title>\n<meta name=\"description\" content=\"Dark Protocol is a zero-knowledge privacy pool for Solana, built by the Dark x402 team. This is the story of what we built, how hard we tried to break it, and the machine-checked proof we started with Harmonic's Aristotle \u2014 until the credits ran out. We're looking for a sponsor to help us finish it.\">\n<style>\n  :root{\n    --bg:#05060a; --bg2:#0a0c14; --card:#0d1019; --line:#1c2130;\n    --text:#e8eaf2; --muted:#9aa3b8; --faint:#6b7390;\n    --purple:#9945FF; --green:#14F195; --amber:#ffb454; --red:#ff6b7a;\n    --grad:linear-gradient(92deg,#9945FF 0%,#14F195 100%);\n  }\n  *{margin:0;padding:0;box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,Helvetica,Arial,sans-serif;line-height:1.65;-webkit-font-smoothing:antialiased}\n  .mono{font-family:ui-monospace,\"SF Mono\",SFMono-Regular,Menlo,Consolas,monospace}\n  code{font-family:ui-monospace,\"SF Mono\",SFMono-Regular,Menlo,Consolas,monospace;font-size:.92em;background:var(--bg2);border:1px solid var(--line);border-radius:5px;padding:1px 5px}\n  .wrap{max-width:880px;margin:0 auto;padding:0 22px}\n  a{color:var(--green);text-decoration:none}\n  a:hover{text-decoration:underline}\n\n  /* header */\n  header{border-bottom:1px solid var(--line);background:rgba(5,6,10,.85);position:sticky;top:0;backdrop-filter:blur(8px);z-index:10}\n  .nav{display:flex;align-items:center;justify-content:space-between;padding:14px 0}\n  .brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.04em}\n  .brand .dot{width:11px;height:11px;border-radius:3px;background:var(--grad)}\n  .brand small{color:var(--muted);font-weight:500;letter-spacing:.08em}\n  .nav .mono{font-size:12px;color:var(--muted)}\n\n  /* article */\n  .backlink{display:inline-block;margin:34px 0 0;font-size:14px;color:var(--muted)}\n  .backlink:hover{color:var(--green)}\n  .kicker{font-size:12px;letter-spacing:.28em;color:var(--green);text-transform:uppercase;margin:26px 0 16px}\n  h1{font-size:clamp(30px,5vw,44px);line-height:1.18;font-weight:800;letter-spacing:-.01em}\n  h1 .grad{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .standfirst{margin-top:20px;font-size:18.5px;line-height:1.6;color:var(--muted);font-style:italic;max-width:700px}\n  .hero-img{margin:34px 0 6px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--card)}\n  .hero-img img{display:block;width:100%;height:auto}\n  .hero-cap{font-size:12.5px;color:var(--faint);margin-bottom:8px}\n  article{padding:10px 0 6px}\n  article h2{font-size:25px;font-weight:750;letter-spacing:-.01em;margin:40px 0 14px;padding-top:28px;border-top:1px solid var(--line)}\n  article h2:first-of-type{border-top:none;padding-top:6px}\n  article p{margin-bottom:15px;color:#cdd3e2;font-size:16.5px}\n  article p strong, article li strong{color:var(--text)}\n  article ol, article ul{margin:6px 0 18px 22px;color:#cdd3e2;font-size:16px}\n  article li{margin-bottom:9px}\n  article li::marker{color:var(--purple);font-weight:700}\n  .statusbox{background:rgba(255,180,84,.05);border:1px solid rgba(255,180,84,.28);border-radius:14px;padding:20px 24px;margin:30px 0 8px}\n  .statusbox p{color:#cdd3e2;font-size:15px;font-style:italic;margin:0}\n  .follow{border-top:1px solid var(--line);margin-top:34px;padding-top:22px;color:var(--muted);font-size:15px}\n\n  footer{border-top:1px solid var(--line);padding:34px 0 54px;color:var(--muted);font-size:13.5px;margin-top:38px}\n  footer .row{display:flex;flex-wrap:wrap;gap:8px 22px;justify-content:space-between}\n  .fineprint{margin-top:14px;font-size:12.5px;color:#5f6b7f}\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"wrap nav\">\n    <div class=\"brand\"><span class=\"dot\"></span>DARK&nbsp;PROTOCOL <small>\u00b7 BY DARKX402</small></div>\n    <div class=\"mono\">solana \u00b7 zero-knowledge \u00b7 formally verified</div>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <a class=\"backlink\" href=\"/dark-protocol\">\u2190 Back to Dark Protocol</a>\n\n  <div class=\"kicker\">The full story \u00b7 November 19, 2026</div>\n  <h1>Dark Protocol: A Year of Building Private Solana \u2014 <span class=\"grad\">and the Proof We Ran Out of Fuel to Finish</span></h1>\n  <p class=\"standfirst\">Dark Protocol is a zero-knowledge privacy pool for Solana, built by the Dark x402 team. This is the story of what we built, how hard we tried to break it, and the machine-checked proof we started with Harmonic's Aristotle \u2014 until the credits ran out. We're looking for a sponsor to help us finish it.</p>\n\n  <div class=\"hero-img\"><img src=\"/dark-protocol/article-hero.webp\" alt=\"A circuit Merkle tree \u2014 purple roots rising into green branches \u2014 above a black pool holding a single golden note, inside an obsidian vault hall\"></div>\n  <p class=\"hero-cap\">The pool, the tree, and the note: every deposit a leaf, every withdrawal a proof.</p>\n\n  <article>\n\n    <h2>Why privacy on Solana needs more than a promise</h2>\n    <p>On a public blockchain, every payment leaves a trail anyone can follow forever. Dark Protocol breaks that trail without asking you to trust us: you deposit SOL into a shared pool, hold a private cryptographic note, and later withdraw to a fresh wallet using a zero-knowledge proof that shows \"I own a valid note\" without revealing which deposit was yours. No public link between the two wallets. No operator who can peek, freeze, or walk off with the funds \u2014 there's no operator at all, only code running on Solana that anyone can read.</p>\n    <p>But a privacy pool is only worth using if its rules can't be bent. It must never pay out more than was deposited. Never accept a forged proof. Never let the same note be spent twice. Never contain a backdoor. \"Trust us, we tested it\" is not an answer. So over the past year, we set out to earn a better one.</p>\n\n    <h2>The year of work</h2>\n    <p><strong>We started by tearing our own house down.</strong> Our first security audit of the original Dark DeFi codebase returned 39 findings \u2014 6 critical, 8 high \u2014 including placeholder cryptography where real zero-knowledge proofs should have been. Rather than patch around it, we ordered a complete rewrite: real Groth16 proofs over BN254, circomlib Poseidon hashing throughout, a depth-20 Merkle tree of notes, and a withdraw circuit of 13,162 constraints.</p>\n    <p><strong>Then we attacked the rewrite.</strong> A hostile re-audit found what testing hadn't: a critical flaw (we track it as NEW-1) where the amount in a deposit wasn't cryptographically bound to the note it created. Left in place, a 1-lamport deposit could have been dressed up to drain the pool. We fixed it at the root \u2014 the program now computes the bound leaf on-chain, <code>Poseidon(commitment, amount)</code>, and the circuit proves membership of exactly that leaf \u2014 and added a drain regression test at every layer of the stack so it can never quietly come back.</p>\n    <p><strong>Then we rehearsed the whole lifecycle on devnet.</strong> Deposits and withdrawals end to end, including a withdrawal routed through a third-party relayer. A replayed withdrawal: rejected. A proof tampered with by a single lamport: rejected. The NEW-1 drain attack, attempted for real: rejected. The books balanced to the lamport \u2014 7,000,001 lamports deposited across the rehearsal, 6,500,000 withdrawn, the remainder exactly the unspent test notes. Along the way we replaced our Poseidon implementation with Solana's native <code>sol_poseidon</code> syscall (~819 compute units per hash, byte-for-byte identical outputs proven on-chain before the swap) and landed final costs of roughly 25k CU to initialize, ~35k CU per deposit, and ~125\u2013131k CU per withdrawal \u2014 practical numbers for mainnet. Every test suite passes: 20/20 program, 34/34 client, 13/13 ZK, 7/7 SDK, 3/3 indexer.</p>\n    <p><strong>And we prepared the trusted setup properly.</strong> A production Groth16 deployment needs a multi-party ceremony so no single person ever holds the toxic waste that could forge proofs. We imported the Hermez perpetual powers-of-tau at 2^15 and verified it bit-for-bit against its pinned BLAKE2b-512 hash, built and rehearsed the full contributor kit, and drafted the ceremony transcript and contributor materials. The ceremony runs before mainnet. No shortcuts.</p>\n\n    <h2>The proof we started \u2014 and where it stopped</h2>\n    <p>Testing checks examples. We wanted proof that checks <em>everything</em>. So we took Dark Protocol to <strong>Aristotle, Harmonic's formal verification engine</strong>, which translates our Rust program into a mathematical model and proves \u2014 or refutes, with a runnable counterexample \u2014 properties stated in plain English. We submitted seven:</p>\n    <ol>\n      <li><strong>No undefined behavior, no panics</strong> anywhere in the program.</li>\n      <li><strong>Conservation of funds</strong> \u2014 the pool's ledger always equals the sum of successful deposits minus successful withdrawals; donations can't inflate it.</li>\n      <li><strong>Withdraw gating</strong> \u2014 every check fires in exact order, and a rejected proof never burns a user's note.</li>\n      <li><strong>Deposit binding</strong> \u2014 the NEW-1 property: the amount is sealed to the note, mathematically.</li>\n      <li><strong>Authority impotence</strong> \u2014 the pool's authority field can never be used as a backdoor; there is no admin path to the funds.</li>\n      <li><strong>Progress</strong> \u2014 an honest user with a valid note can always withdraw; the pool can't brick itself.</li>\n      <li><strong>Root-history integrity</strong> \u2014 the Merkle root history contains only roots the program itself produced.</li>\n    </ol>\n    <p>Harmonic's signup grant gave us 500 credits. On November 18, 2026, we fired the run.</p>\n    <p><strong>Two hours later, the grant was gone \u2014 and the run ended OUT_OF_BUDGET with all seven properties unresolved.</strong> Not proved. Not refuted. No counterexamples \u2014 the verifier didn't find our code wrong; it ran out of fuel in the middle of proving it right. Formal verification of real cryptography-adjacent Rust is simply expensive: the prover was working through a ~1,760-line program whose correctness leans on Poseidon and Groth16 verification at its boundary. We also have a second pilot fully packaged and paused \u2014 eight properties for the on-chain limit orderbook that will settle Dark Percolator trades \u2014 which never got to start.</p>\n    <p>We publish our status page honestly, and it still says what it said the day we deployed it: <em>verification in progress</em>. We're not going to relabel an unfinished proof as a finished one. That's the whole point of doing this in public.</p>\n\n    <h2>What we're asking</h2>\n    <p><strong>We're looking for a sponsor to fund the Aristotle credits to finish the verification we started.</strong></p>\n    <p>Based on the burn rate we observed, completing the seven Dark Protocol properties plausibly takes a further $1,000\u2013$2,000 in credits \u2014 we'd start with the two highest-value properties (deposit binding and conservation of funds) and publish results as they land: proved, refuted with a counterexample we'll fix, or unresolved with the boundary stated plainly. Sponsors get named credit on the protocol page and in the verification report, early access to the full results package, and the knowledge that mainnet privacy on Solana got its proof because they funded it.</p>\n\n    <h2>Why it matters beyond one pool</h2>\n    <p>Dark Protocol is the settlement core of a family we're bringing to Solana mainnet:</p>\n    <ul>\n      <li><strong>Confidential compute</strong> \u2014 TEE-attested execution where the machine itself proves what it ran.</li>\n      <li><strong>Private AI inference</strong> \u2014 Dark x402: model calls that run in the dark and are paid for in the dark, over x402.</li>\n      <li><strong>Private perpetual trading</strong> \u2014 Dark Percolator and Dark Perps: positions the whole world doesn't get to front-run.</li>\n    </ul>\n    <p>Every one of those stands on the same foundation: private value movement whose rules are <em>proven</em>, not promised. The pool is built. The ceremony is staged. The proofs are specified, packaged, and waiting on credits.</p>\n    <p><strong>Help us finish what we started.</strong></p>\n\n    <p class=\"follow\"><strong style=\"color:var(--text)\">Follow the work:</strong> <a href=\"https://darkx402.com/dark-protocol\">darkx402.com/dark-protocol</a> \u00b7 <a href=\"https://protocol.darkx402.com\">protocol.darkx402.com</a> \u00b7 X: <a href=\"https://x.com/0rdlibrary\">@0rdlibrary</a> \u00b7 GitHub: <a href=\"https://github.com/solizardking\">github.com/solizardking</a></p>\n\n    <div class=\"statusbox\">\n      <p>Status at publication: Dark Protocol is live on Solana devnet only. Mainnet is gated on completion of the MPC ceremony and the formal verification above. Nothing in this article is a claim that verification has completed \u2014 yet.</p>\n    </div>\n\n  </article>\n\n  <footer>\n    <div class=\"row\">\n      <div><strong style=\"color:var(--text)\">DARK PROTOCOL</strong> \u00b7 a Dark DeFi project \u00b7 darkx402.com</div>\n      <div class=\"mono\">program (devnet): 2GmpuVGfFVfhiqUWrrhkkWBk3i8TpbTuqyiZNXETA5kL</div>\n    </div>\n    <p class=\"fineprint\">Status as of November 19, 2026: live on Solana devnet for testing; formal verification in progress (Aristotle project \u201cdark-protocol-pilot\u201d); mainnet not launched. Nothing on this page is financial advice, and a system being verified is not a guarantee \u2014 it is evidence, published so you can weigh it yourself.</p>\n  </footer>\n\n</div>\n</body>\n</html>\n";
const HERO_B64 = "";

let heroBytes = null;
function getHero() {
  if (!heroBytes) {
    const bin = atob(HERO_B64);
    heroBytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) heroBytes[i] = bin.charCodeAt(i);
  }
  return heroBytes;
}

const HTML_HEADERS = {
  'content-type': 'text/html; charset=utf-8',
  'cache-control': 'public, max-age=300'
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let p = url.pathname;
    // Normalise: strip a leading /dark-protocol prefix so the same routes
    // work on darkx402.com (zone route) and protocol.darkx402.com (custom domain).
    if (p === '/dark-protocol') p = '/';
    else if (p.startsWith('/dark-protocol/')) p = p.slice('/dark-protocol'.length);
    if (p.length > 1 && p.endsWith('/')) p = p.slice(0, -1);

    if (p === '/article') {
      return new Response(ARTICLE_PAGE, { headers: HTML_HEADERS });
    }
    if (p === '/article-hero.webp') {
      return new Response(getHero(), {
        headers: {
          'content-type': 'image/webp',
          'cache-control': 'public, max-age=86400'
        }
      });
    }
    // Everything else keeps the original behaviour: serve the explainer page.
    return new Response(MAIN_PAGE, { headers: HTML_HEADERS });
  }
};
